      .background(Color.secondary.opacity(0.08), in: RoundedRectangle(cornerRadius: 10))\n    }\n}\n\nVStack(alignment: .leading, spacing: 20) {\n    VStack(alignment: .leading, spacing: 2) {\n        Text(\"本周健康\").font(.title3.bold())\n        Text(\"\\(days.first!.date.formatted(.dateTime.month().day())) – \\(days.last!.date.formatted(.dateTime.month().day()))\")\n            .font(.subheadline)\n            .foregroundStyle(.secondary)\n    }\n    LazyVGrid(columns: [GridItem(.adaptive(minimum: 150), spacing: 8)], spacing: 8) {\n        ForEach(kpis, id: \\.title) { item in Kpi(item: item) }\n    }\n    VStack(alignment: .leading, spacing: 8) {\n        Text(\"每日步数\").font(.headline)\n        HistoryBars(values: days.map { $0.steps }, tint: .orange, highlights: days.indices.filter { days[$0].steps >= step_goal }, reference: step_goal, referenceLabel: \"目标 \\(step_goal)\",\n                    labels: [days.first!.date.formatted(.dateTime.weekday()), days.last!.date.formatted(.dateTime.weekday())])\n            .frame(height: 150)\n    }\n    VStack(alignment: .leading, spacing: 8) {\n        Text(\"睡眠\").font(.headline)\n        SeriesLines(series: [days.map { $0.sleep_hours }, days.map { $0.sleep_hours_last_week }], labels: [\"本周\", \"上周\"], tint: .indigo,\n                    xLabels: [days.first!.date.formatted(.dateTime.weekday()), days.last!.date.formatted(.dateTime.weekday())],\n                    texts: [\"\\(days.last!.sleep_hours, specifier: \"%.1f\") 小时\", \"\\(days.last!.sleep_hours_last_week, specifier: \"%.1f\") 小时\"])\n            .frame(height: 160)\n    }\n    VStack(alignment: .leading, spacing: 8) {\n        Text(\"明细\").font(.headline)\n        Grid(alignment: .leading, horizontalSpacing: 12, verticalSpacing: 8) {\n            GridRow {\n                head(\"日期\"); head(\"步数\").gridColumnAlignment(.trailing); head(\"睡眠\").gridColumnAlignment(.trailing); head(\"静息心率\").gridColumnAlignment(.trailing)\n            }\n            Divider()\n            ForEach(days, id: \\.date) { day in\n                GridRow {\n                    Text(day.date.formatted(.dateTime.month().day().weekday()))\n                    Text(day.steps.formatted()).monospacedDigit()\n                    Text(\"\\(day.sleep_hours, specifier: \"%.1f\") h\").monospacedDigit()\n                    Text(\"\\(day.resting_hr) bpm\").monospacedDigit()\n                }\n            }\n        }\n        .font(.subheadline)\n    }\n}"}
