{"data":{"options":["温泉","徒步","美食","古镇","海边","博物馆","少走路"],"paces":[{"id":"relaxed","name":"放松"},{"id":"balanced","name":"适中"},{"id":"packed","name":"紧凑"}],"subtitle":"选好后发给 floo，它按这些找地方和车票。","title":"周末去哪儿"},"source":"struct TripForm: View {\n    @State private var pace = \"relaxed\"\n    @State private var budget = 3000.0\n    @State private var nights = 2\n    @State private var wants: [String] = []\n    @State private var note = \"\"\n    @State private var sent = false\n\n    var summary: String {\n        \"周末出行偏好：节奏\\(paces.first { $0.id == pace }!.name)，\\(nights) 晚，预算每人 ¥\\(Int(budget / 100) * 100)\"\n            + (wants.isEmpty ? \"\" : \"，想要\" + wants.joined(separator: \"、\"))\n            + (note.isEmpty ? \"\" : \"。补充：\\(note)\")\n    }\n\n    var body: some View {\n        VStack(alignment: .leading, spacing: 18) {\n            VStack(alignment: .leading, spacing: 2) {\n                Text(title).font(.title3.bold())\n                Text(subtitle).font(.subheadline).foregroundStyle(.secondary)\n            }\n            VStack(alignment: .leading, spacing: 8) {\n                Text(\"节奏\").font(.subheadline.weight(.semibold))\n                Picker(\"节奏\", selection: $pace) {\n                    ForEach(paces, id: \\.id) { option in Text(option.name).tag(option.id) }\n                }\n                .pickerStyle(.segmented)\n            }\n            VStack(alignment: .leading, spacing: 8) {\n                HStack {\n                    Text(\"预算（每人）\").font(.subheadline.weight(.semibold))\n                    Spacer()\n                    Text(\"¥\\(Int(budget / 100) * 100)\").font(.subheadline).monospacedDigit().foregroundStyle(.secondary)\n                }\n                Slider(value: $budget, in: 1000...8000)\n            }\n            VStack(alignment: .leading, spacing: 8) {\n                Text(\"住几晚\").font(.subheadline.weight(.semibold))\n                Picker(\"住几晚\", selection: $nights) {\n                    ForEach(1...3, id: \\.self) { n in Text(\"\\(n) 晚\").tag(n) }\n                }\n                .pickerStyle(.segmented)\n            }\n            VStack(alignment: .leading, spacing: 8) {\n                Text(\"想要\").font(.subheadline.weight(.semibold))\n                Flow(spacing: 8, lineSpacing: 8) {\n                    ForEach(options, id: \\.self) { option in\n                        let on = wants.contains(option)\n                        Button {\n                            if on { wants.removeAll { $0 == option } } else { wants.append(option) }\n                        } label: {\n                            Label(option, systemImage: on ? \"checkmark\" : \"plus\")\n                                .font(.subheadline)\n                                .padding(.horizontal, 12)\n                                .padding(.vertical, 6)\n                                .fontWeight(on ? .semibold : .regular)\n                                .background(Color.primary.opacity(on ? 0.14 : 0.06), in: Capsule())\n                        }\n                        .buttonStyle(.plain)\n                    }\n                }\n            }\n            TextField(\"还有什么要说的\", text: $note, axis: .vertical)\n            HStack {\n                if sent {\n                    Label(\"已发给 floo\", systemImage: \"checkmark.circle.fill\").font(.subheadline).foregroundStyle(.green)\n                }\n                Spacer()\n                Button(sent ? \"再发一次\" : \"发给 floo\") {\n                    let reply = await send(message: summary)\n                    sent = reply != nil\n                }\n            }\n        }\n    }\n}\n\nTripForm()"}
